}
inline int launch(qkg_simt_call_v2 const& d,qkg_simt_config_v1 const& f) {
    int body=q8_refresh_body(d,f);
    if(!body) return QKG_INVALID;
    auto const& c=d.call;
    auto stream=static_cast<hggcStream_t>(c.stream);
    dim3 grid(c.n/(f.columns*f.values),c.rows);
    if(body==1 && f.columns==4 && f.warps==8) {
        kernel_1_4_8<<<grid,8*32,0,stream>>>(c);
        return hggcGetLastError()==hggcSuccess ? QKG_OK : QKG_RUNTIME;
    }
    if(body==1 && f.columns==8 && f.warps==4) {
        kernel_1_8_4<<<grid,4*32,0,stream>>>(c);
        return hggcGetLastError()==hggcSuccess ? QKG_OK : QKG_RUNTIME;
    }
    if(body==3 && f.columns==4 && f.warps==8) {
        kernel_3_4_8<<<grid,8*32,0,stream>>>(c);
        return hggcGetLastError()==hggcSuccess ? QKG_OK : QKG_RUNTIME;
    }
    if(body==3 && f.columns==8 && f.warps==4) {
        kernel_3_8_4<<<grid,4*32,0,stream>>>(c);
        return hggcGetLastError()==hggcSuccess ? QKG_OK : QKG_RUNTIME;
    }
    if(body==4 && f.columns==4 && f.warps==8) {
        kernel_4_4_8<<<grid,8*32,0,stream>>>(c);
        return hggcGetLastError()==hggcSuccess ? QKG_OK : QKG_RUNTIME;
    }
    if(body==4 && f.columns==8 && f.warps==4) {
        kernel_4_8_4<<<grid,4*32,0,stream>>>(c);
        return hggcGetLastError()==hggcSuccess ? QKG_OK : QKG_RUNTIME;
    }
    if(body==5 && f.columns==4 && f.warps==8) {
        kernel_5_4_8<<<grid,8*32,0,stream>>>(c);
        return hggcGetLastError()==hggcSuccess ? QKG_OK : QKG_RUNTIME;
    }
    if(body==5 && f.columns==8 && f.warps==4) {
        kernel_5_8_4<<<grid,4*32,0,stream>>>(c);
        return hggcGetLastError()==hggcSuccess ? QKG_OK : QKG_RUNTIME;
    }
    return QKG_INVALID;
}
